SELECT 
FROM t_dd_program p JOIN t_dd_program_version v ON v.program_id = p.program_id

    BINARY p.jurisdiction_code = BINARY #{jurisdictionCode}
    AND BINARY p.status = BINARY #{status}

ORDER BY p.jurisdiction_code, p.program_code, v.version_no DESC LIMIT 201

SELECT 
FROM t_dd_program p JOIN t_dd_program_version v ON v.program_id = p.program_id
WHERE v.program_version_id IN #{id}
